package com.jobmatcher.controller;
import com.jobmatcher.dto.AuthDtos.*;import com.jobmatcher.model.User;import com.jobmatcher.repository.UserRepository;import com.jobmatcher.security.TokenService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository users;private final PasswordEncoder encoder;private final TokenService tokens;public AuthController(UserRepository u,PasswordEncoder e,TokenService t){users=u;encoder=e;tokens=t;}private UserView view(User u){return new UserView(u.getId(),u.getName(),u.getEmail(),u.getQualification(),u.getExperience(),u.getSkills());}private AuthResponse response(User u){return new AuthResponse(tokens.create(u.getId()),view(u));}
 @PostMapping("/signup") public ResponseEntity<?> signup(@Valid @RequestBody Signup r){if(users.existsByEmail(r.email().toLowerCase()))return ResponseEntity.status(409).body(Map.of("error","An account with this email already exists."));User u=users.save(new User(r.name().trim(),r.email(),encoder.encode(r.password()),r.qualification(),r.experience()));return ResponseEntity.status(201).body(response(u));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody Login r){User u=users.findByEmail(r.email().toLowerCase()).orElse(null);if(u==null||!encoder.matches(r.password(),u.getPasswordHash()))return ResponseEntity.status(401).body(Map.of("error","Invalid email or password."));return ResponseEntity.ok(response(u));}}
